#[derive(Debug, Clone, PartialEq, Eq)]
pub enum VoteChoices {
    Named(Box<VoteChoicesNamed>),
    Objects(Box<VoteChoicesObjects>),
    Players(Box<VoteChoicesPlayers>),
}
impl<'de> Deserialize<'de> for VoteChoices {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        #[allow(unused_mut)]
        match Value::deserialize(deserializer)? {
        Value::Object(mut object) => match tag(&object, "choices").as_deref() {
            Some("\"named\"") => { object.remove("choices");strict(Value::Object(object)).map(VoteChoices::Named).map_err(|e| format!("VoteChoices::Named: {e}")) },
            Some("\"objects\"") => { object.remove("choices");strict(Value::Object(object)).map(VoteChoices::Objects).map_err(|e| format!("VoteChoices::Objects: {e}")) },
            Some("\"players\"") => { object.remove("choices");strict(Value::Object(object)).map(VoteChoices::Players).map_err(|e| format!("VoteChoices::Players: {e}")) },
            other => Err(format!("VoteChoices: unknown choices {other:?}")),
        },
        other => Err(format!("VoteChoices: unexpected {other}")),
        }
        .map_err(D::Error::custom)
    }
}

